1038	+package at.fhv.audioracer.simulator.player.pivot.util;
1039	+
1040	+import java.lang.reflect.Constructor;
1041	+import java.lang.reflect.InvocationHandler;
1042	+import java.lang.reflect.Method;
1043	+import java.lang.reflect.Proxy;
1044	+
1045	+import org.apache.pivot.wtk.ApplicationContext;
1046	+
1047	+public class PivotThreadProxy implements InvocationHandler {
1048	+	
1049	+	private Object _base;
1050	+	private Object _proxy;
1051	+	
1052	+	public PivotThreadProxy(Object base) throws IllegalArgumentException {
1053	+		if (base == null) {
1054	+			throw new IllegalArgumentException("base must not be null!");
1055	+		}
1056	+		
1057	+		_base = base;
1058	+		_proxy = createProxy(_base.getClass());
1059	+	}
1060	+	
1061	+	private Object createProxy(Class<?> baseClass) {
1062	+		Class<?> proxyClass = Proxy.getProxyClass(baseClass.getClassLoader(),
1063	+				baseClass.getInterfaces());
1064	+		Constructor<?> constructor;
1065	+		try {
1066	+			constructor = proxyClass.getConstructor(InvocationHandler.class);
1067	+			return constructor.newInstance(this);
1068	+		} catch (Exception e) {
1069	+			throw new RuntimeException("Couldn't create the requested proxy object.", e);
1070	+		}
1071	+	}
1072	+	
1073	+	public Object getProxy() {
1074	+		return _proxy;
1075	+	}
1076	+	
1077	+	@Override
1078	+	public Object invoke(Object proxy, final Method method, final Object[] args) throws Throwable {
1079	+		ApplicationContext.queueCallback(new Runnable() {
1080	+			
1081	+			@Override
1082	+			public void run() {
1083	+				try {
1084	+					method.invoke(_base, args);
1085	+				} catch (Exception e) {
1086	+					throw new RuntimeException(
1087	+							"Unexpected invocation exception: " + e.getMessage(), e);
1088	+				}
1089	+			}
1090	+		});
1091	+		
1092	+		return null;
1093	+	}
1094	+}
